import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound39BridgeSoundOracle extends GhidraScript{
 static final long RET=0x12345000L,MIX=0x12346000L,S=0x7fff0000L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(i*8);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}long hash(byte[]b){long h=2166136261L;for(byte v:b)h=((h^(v&255))*16777619L)&0xffffffffL;return h;}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<2048;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int bank=s%5,cycle=s/5%8;long table=Integer.toUnsignedLong(getInt(toAddr(0x4a0dacL+bank*4)));int id=new int[]{1,2,3,4,5,1,2,3}[cycle];long descriptor=0;for(int k=0;k<1024;k++){short n=getShort(toAddr(table+k*44+2));if(n==-1)break;if(n==id){descriptor=table+k*44;break;}}if(descriptor==0)throw new Exception("id"+id+"bank"+bank);
 int[]deltas={-49,-48,0,672,673,512,32767,-32768};int cx=new int[]{0,500,32760,-32760}[s/40%4],cy=new int[]{0,500,-32760,32760}[s/160%4],x=(short)(cx+deltas[s/8%8]),y=(short)(cy+deltas[s/64%8]);int width=new int[]{640,0,32767,-32768}[s/512%4],height=480;int now=s/80%2==0?0:120;put(e,0x6815a0,4,table);put(e,descriptor+28,2,0);put(e,0x680d08,2,now);put(e,0x6323a0,1,s/10%2);put(e,0x4a6f4e,1,cycle);put(e,0x4d18ee,1,s%3==0?0:s%3==1?1:255);put(e,0x4a6e6f,1,s/20%2);put(e,0x4a6f4f,1,s/30%2);put(e,0x681588,4,0x12340000L+(s*17&65535));put(e,0x622cb8,2,cx);put(e,0x622cba,2,cy);put(e,0x498c24,2,width);put(e,0x498c20,2,height);put(e,0x474214,4,MIX);byte[]terrain=new byte[32768],pool=new byte[500];for(int i=0;i<terrain.length;i++)terrain[i]=(byte)(s+i*17);for(int i=0;i<pool.length;i++)pool[i]=(byte)(s+i*19);e.writeMemory(toAddr(0x586aaa),terrain);e.writeMemory(toAddr(0x595b12),pool);long beforeTerrain=hash(terrain),beforePool=hash(pool);for(long pc:new long[]{RET,MIX,0x460910})e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",x);e.writeRegister("EDX",y);if(!e.run(toAddr(0x41f870),null,monitor))throw new Exception(e.getLastError());int played=0;while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue();if(pc!=MIX)throw new Exception("unexpected"+Long.toHexString(pc));played++;long sp=e.readRegister("ESP").longValue();e.writeRegister("EAX",s%2==0?-1:3);long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 out.println(s+","+bank+","+x+","+y+","+cx+","+cy+","+width+","+height+","+cycle+","+id+","+played+","+read(e,0x4a6f4e,1)+","+read(e,0x4d18ee,1)+","+read(e,0x681588,4)+","+(short)read(e,descriptor+28,2)+","+(beforeTerrain==hash(e.readMemory(toAddr(0x586aaa),32768))?0:1)+","+(beforePool==hash(e.readMemory(toAddr(0x595b12),500))?0:1));}finally{e.dispose();}}}}
}